----------------------------------------------行权改造相关数据字典调整 START-------------------------------------------
/** 添加数据字典【行权回售申请交易处理】**/
delete from SYS_DATADICT where dict_code = 'EXEC_RESALEAPPLY_DEAL';
delete from SYS_DATADICT_LIST where dict_code = 'EXEC_RESALEAPPLY_DEAL';

/** 数据字典【交易方向】增加行权-回售申请、行权-赎回结转**/
delete from SYS_DATADICT_LIST where dict_code = 'PS' and item_code in ('T67','T68');

/** 数据字典【分支类型】增加行权**/
delete from SYS_DATADICT_LIST where dict_code = 'BRANCH_TYPE' and item_code in ('D03');

/** 数据字典【行权状态】增加放弃行权**/
delete from SYS_DATADICT_LIST where dict_code = 'EXEC_TYPE' and item_code in ('04');

/** 数据字典【指令类型】增加行权回售、赎回指令类型**/
delete from SYS_DATADICT_LIST where dict_code = 'ORDER_TYPE' and item_code in ('N1370','N1371','N1372','N1373','N1374',
'N1375','N1376','N1377','N1378','N1379','N1380','N1381');

----------------------------------------------行权改造相关数据字典调整 END-------------------------------------------

----------------------------------------------增加债券行权的账套参数 START-------------------------------------------
/** dodify by yanya on 20210317 增加债券行权的账套参数**/
DELETE FROM BOK_BOOKSET_EXT WHERE PARAM_CODE in ('EXEC_PRICE_CAL_TYPE','EXEC_RESALEAPPLY_DEAL');


SELECT A.BOOKSET_ID,B.PARAM_CODE,B.PARAM_VALUE,B.PARAM_NAME,B.REMARK,
B.CREATE_USER,B.CREATE_DEPT,B.CREATE_TIME,B.UPDATE_USER,B.UPDATE_TIME,PARAM_TYPE
FROM BOK_BOOKSET A,BOK_BOOKSET_EXT B
WHERE A.BOOKSET_ID_TMPL = B.BOOKSET_ID
AND B.PARAM_CODE in ('EXEC_PRICE_CAL_TYPE','EXEC_RESALEAPPLY_DEAL') 
AND A.BOOKSET_TYPE ='02'
AND A.BOOKSET_ID_TMPL IN ('00000000000000000002','00000000000000000003','00000000000000000004','SUBJECT_INTERNAL_001');
----------------------------------------------增加债券行权的账套参数 END-------------------------------------------

